/**
 * Generate reference docs from the code that enforces them, so they cannot drift:
 *   docs/MODULES.md, docs/EVENT_TAXONOMY.md, docs/CONNECTOR_CAPABILITIES.md, docs/POLICY_MATRIX.md
 * Usage: npm run docs            (write)
 *        npm run docs -- --check (fail if any generated file is out of date; used in CI)
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CAPABILITY_SEEDS } from '../packages/connectors/src/capabilities.js';
import { ACTION_TYPES, EVENT_TYPES, MODULES, RISK_CATEGORIES } from '../packages/contracts/src/index.js';
import { DEFAULT_APPROVERS, POLICY_VERSION } from '../packages/policies/src/index.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const HEADER = '<!-- Generated by scripts/gen-docs.ts. Do not edit by hand; run `npm run docs`. -->\n\n';
const cell = (v: unknown) =>
  String(v ?? '—')
    .replaceAll('|', '\\|')
    .replaceAll('\n', ' ');
const table = (head: string[], rows: unknown[][]) => [`| ${head.join(' | ')} |`, `| ${head.map(() => '---').join(' | ')} |`, ...rows.map((r) => `| ${r.map(cell).join(' | ')} |`)].join('\n');

function modules(): string {
  return `${HEADER}# Module registry (M01–M24)\n\nThe canonical 24-module map (product plan P0). Each module owns its API prefix; consequential writes from any module go through M23.\n\n${table(
    ['ID', 'Module', 'Purpose', 'API prefix', 'Depends on', 'Aliases'],
    MODULES.map((m) => [m.id, m.name, m.purpose, `\`${m.apiPrefix}\``, m.dependsOn.join(', ') || '—', m.aliases.join(', ')]),
  )}\n`;
}

function events(): string {
  const groups = new Map<string, [string, number][]>();
  for (const [type, version] of Object.entries(EVENT_TYPES)) {
    const g = type.split('.')[0]!;
    groups.set(g, [...(groups.get(g) ?? []), [type, version]]);
  }
  const body = [...groups.entries()]
    .map(
      ([g, list]) =>
        `## ${g}\n\n${table(
          ['Event type', 'Version'],
          list.map(([t, v]) => [`\`${t}\``, v]),
        )}`,
    )
    .join('\n\n');
  return `${HEADER}# Event taxonomy\n\nNaming: \`<module>.<aggregate>.<past_tense_verb>\`. Events are written to the transactional outbox in the same transaction as the state change and delivered at least once (handlers are idempotent). A version increases on a breaking payload change.\n\nEnvelope: \`{ id, tenantId, eventType, version, aggregateType, aggregateId, actor, payload, causationId, occurredAt }\`.\n\n${body}\n`;
}

function capabilities(): string {
  const rows = CAPABILITY_SEEDS.map((c) => [c.platform, `\`${c.capability}\``, c.apiVersion, c.supported ? 'yes' : 'no', c.requiredScopes.join(', ') || '—', c.appReviewRequired, c.rateLimitPolicy ? JSON.stringify(c.rateLimitPolicy) : '—', c.fallback ?? '—', c.notes ?? '']);
  return `${HEADER}# Connector capability registry\n\nA connector can only call a capability declared here and present in the database registry with a matching API version (M24). Live approval status (app review, scopes granted to a connection) is checked at proposal and again at preflight. Values below are the shipped seeds; operators keep the database registry current.\n\n${table(['Platform', 'Capability', 'API version', 'Supported', 'Required scopes', 'App review', 'Local rate limit', 'Fallback', 'Notes'], rows)}\n`;
}

const RULES: [string, string][] = [
  ['R-ALLOWLIST', 'Action type must be on the deny-by-default allowlist and supported; unsupported types (SMS, WhatsApp, payouts) are denied with their blocker reference.'],
  ['R-KILL', 'No engaged kill switch in scope (system, tenant, connector, object, model, agent). Re-checked immediately before the provider call.'],
  ['R-CAPABILITY', 'Capability exists in the registry with the configured API version; app-review requirements are met; the configured provider API version has not reached its sunset (FG-P2-001).'],
  ['R-CONNECTION', 'Connection is active, healthy enough, and holds every required scope.'],
  ['R-EVIDENCE', 'Agent/system proposals need admitted, current evidence permitted for autonomous execution (D-023); human proposals without evidence need approval.'],
  ['R-CHILDREN / R-SENSITIVE', "Children's data and sensitive or proxy attributes never drive targeting or messaging (BLOCK)."],
  ['R-JURISDICTION', 'Public, messaging, spend, pricing and export actions need target geographies with a legal-approved rule pack; otherwise a legal approval group is added.'],
  ['R-CLAIMS', 'Cited claims exist, are approved and unexpired; regulated claims add legal approval.'],
  ['R-ENDORSEMENT / R-PERSONA', 'Material connections and synthetic personas require disclosure text; personas must be approved and not suspended.'],
  ['R-ASSETS', 'Referenced assets exist and are publish-eligible (rights manifest + QA).'],
  ['R-MESSAGING', 'Recipient not suppressed; commercial mail needs current consent, a complete sender identity (CAN-SPAM), configured frequency caps; quiet hours defer execution.'],
  ['R-PLATFORM', 'Platform-specific rules, e.g. TikTok unaudited apps may only post SELF_ONLY; YouTube synthetic media must be flagged.'],
  ['R-EXPERIMENT', 'Experiment exists and is startable; high-risk experiments always require human approval.'],
  ['R-AUTONOMY / R-SPEND / R-AUDIENCE', 'Tenant category policy: deny, approval_required, or pre-authorized within per-action/24 h spend ceilings and audience-size limits. Unconfigured categories always require approval.'],
];

function policy(): string {
  const actions = table(
    ['Action type', 'Provider', 'Category', 'Spend', 'Public', 'Contacts people', 'Verification', 'Rollback', 'Supported'],
    ACTION_TYPES.map((a) => [`\`${a.type}\``, a.provider, a.category, a.affectsSpend ? 'yes' : '', a.publicFacing ? 'yes' : '', a.contactsPeople ? 'yes' : '', a.verification, a.rollback, a.supported ? 'yes' : `no (${(a as { blockerRef?: string }).blockerRef ?? 'blocked'})`]),
  );
  const approvers = table(
    ['Risk category', 'Default approver roles (when the tenant has not configured the category)'],
    RISK_CATEGORIES.map((c) => [c, DEFAULT_APPROVERS[c].join(', ')]),
  );
  return `${HEADER}# Policy matrix\n\nEvery consequential write is an ActionRequest evaluated by the deterministic policy engine (\`${POLICY_VERSION}\`) at proposal and again at preflight. Outcomes: ALLOW (pre-authorized), REQUIRE_APPROVAL (one approval per required group, distinct people, never the proposer, MFA, bound to the action hash), or DENY. No action is successful until VERIFIED by independent read-back.\n\n## Action allowlist\n\n${actions}\n\n## Default approver roles\n\n${approvers}\n\nA legal group (\`legal_approver\` or \`owner\`) is added by R-JURISDICTION and R-CLAIMS when needed.\n\n## Rules\n\n${table(['Rule', 'What it enforces'], RULES)}\n`;
}

const outputs: Record<string, string> = {
  'docs/MODULES.md': modules(),
  'docs/EVENT_TAXONOMY.md': events(),
  'docs/CONNECTOR_CAPABILITIES.md': capabilities(),
  'docs/POLICY_MATRIX.md': policy(),
};

const check = process.argv.includes('--check');
const stale: string[] = [];
for (const [rel, content] of Object.entries(outputs)) {
  const file = path.join(root, rel);
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8').replaceAll('\r\n', '\n') : null;
  if (check) {
    if (current !== content) stale.push(rel);
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
  }
}
if (check && stale.length) {
  console.error(`generated docs are out of date: ${stale.join(', ')} (run npm run docs)`);
  process.exit(1);
}
console.log(check ? 'generated docs up to date' : `wrote ${Object.keys(outputs).join(', ')}`);
